mapper.select:
SELECT po.id, po.purchase_no AS purchaseNo, po.supplier_id AS supplierId, s.name AS supplierName, po.total_qty AS totalQty, po.total_amount AS totalAmount, po.status, po.create_user_id AS createUserId, u.real_name AS createUserName, DATE_FORMAT(po.order_time, '%Y-%m-%d') AS orderTime, DATE_FORMAT(po.arrival_time, '%Y-%m-%d') AS arrivalTime, po.remark FROM purchase_order po LEFT JOIN supplier s ON po.supplier_id = s.id LEFT JOIN sys_user u ON po.create_user_id = u.id WHERE po.is_delete = 0
AND po.purchase_no LIKE CONCAT('%', #{query.purchaseNo}, '%')
AND po.supplier_id = #{query.supplierId}
AND po.status = #{query.status}
AND po.order_time >= #{query.startTime}
AND po.order_time <= #{query.endTime}
ORDER BY po.create_time DESC
